import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"周易闡真 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"周易闡真 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/chanzhen/024.md","filePath":"classics/chanzhen/024.md"}'),s={name:"classics/chanzhen/024.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：剝，剝也。柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。</p></blockquote><h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><p>初六：剝床以足，蔑貞兇。</p><p>六二：剝床以辨，蔑貞兇。</p><p>六三：剝之，無咎。</p><p>六四：剝床以膚，兇。</p><p>六五：貫魚以宮人寵，無不利。</p><p>上九：碩果不食。君子得輿，小人剝廬。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：山附於地，剝。上以厚下安宅。</p><p>剝者，消去也。上艮山，下坤地，是山附於地也。山本高，地本低，以山附地，去其高之有餘，厚其低之不足，剝之象也。</p><p>為上者有見於此，知山不附地，則山不著實；上不厚下，則上不安居。以是剝上厚下，使在下者，皆得其所焉。蓋民為邦本，本固邦寧，而在上者，亦安其所居之宅，行無為之治矣。修道之士，有才有智者，亦上也；無才無智者，亦下也。有才不恃，有智不用，剝去才智之有餘，就於才智之不足，以高附低，以實居虛，則高為真高，實為真實，化假為真，止於至善之地而不遷，安居其宅，不為客氣所傷矣。夫仁者，人之安宅也。剝上厚下，顛倒之間，剝即變復。復則能依於仁，生機迴轉，性命有賴，厚下安宅，天機畢露矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>辨，音瓣。</p><p>剝者，消化也。卦德上艮止，下坤順，陰順生而陽止息，且卦體五陰而消一陽，陽氣將盡，陰氣將純，故謂剝。此後天陰消其陽之卦，承上噬嗑而來。噬嗑者，動而必明，所以先窮理也。窮理者，窮其陰陽消長之理耳。</p><p>人秉天地陰陽五行之氣而生身，有命而即有性，性命寓於一身之中矣。當人生之初，性命一家，先天后天混而為一，陰陽未分，邪正未判，圓成之象。及其成人氣足，先天陽極，交於後天。一陰潛生，日復一日，年復一年，陰氣漸盛，陽氣漸弱，不至消盡其陽而不止，如卦體五陰而剝一陽。當此之時，陽不勝陰，其所餘者，幾希之陽耳。</p><p>人若不知，而猶認假為真，有攸往而自恃其強，必至陽氣消盡，不利甚矣。至人於此，有抑陰扶陽之道，不使陰氣消陽於盡，即於此一點陽氣未盡處，順而止之，黜聰毀智，緊閉靈竅，以為返本還元之基。</p><p>蓋不能使陽而不陰者，天地循環之氣機；而能於陰中保陽者，聖人逆運之功力。特以聖人有先天而天弗違之道，能以奪造化、轉生殺也。至於一切常人，順行造化，以陰剝陽，陽氣消盡，化為純陰，不死豈能之乎?</p><p>聖人於剝之一卦，直彖曰：“不利有攸往。”凡惜性命者，可以早悟矣。</p><p>初六，一陰潛生，自下消陽，如剝床以足也。床足之剝，其氣雖微，其害最大，蔑貞之兇，即於此始。此陰氣方進之剝也。</p><p>六二，陰氣浸長，自下而上，如剝床以辨也。辨下是足，辨上是床，陰氣漸升，將上於床，與陽爭權，蔑貞之兇，不旋踵而至矣。此陰氣漸盛之剝也。</p><p>六三，在順體之上，不順陰而順陽，與陽相應，乃安靜之陰，雖在剝時可以無咎。此陰氣順止之剝也。</p><p>六四，陰氣結聚，順升而上，六陽已剝去四陽，陰盛陽弱，上床用事，乃切近之災，如剝床以膚，兇之至矣。此陰氣用事之剝也。</p><p>六五，在止體之中，與陽相親，乃客氣中發現之真陰。真陰現象，不但不傷於陽，而且能統群陰，皆順其陽。以物取之，如一魚前領，而群魚貫後；以人取之，如後以眾宮人進寵於君王。知之者，借真陰以保真陽，則一真百真。剝者不剝，吉無不利，信有然者。此陰氣順陽無剝也。</p><p>上九，在剝之終，諸陽剝去，尚留一陽，猶未剝盡，知之者順而止之，不為群陰所傷，如碩果不食也。果中有仁，存此一仁則生，失此一仁則死，生之死之，只在此一仁得失之間。但此一仁，庶民去之，君子存之。蓋君子知此一仁為生生化化之本，保之守之。不但陰氣不能傷，而且借陰以全陽，如得其輿，安而行之。至於一切小人，順其所欲，知進而不知退，消陽至盡，終歸大化，如剝其廬，自失所庇矣。此聖功能止其剝也。</p><p>六爻之剝，陰傷陽者兇，陰順陽者吉。修道者可不順而止之，以保其陽乎?順而止之，顛倒之間，剝即變復，人能知剝中藏復，於此一陽未盡處下手，則後天中返先天之道得矣。噫!此天機也，知之者能有幾人哉!</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
